import pytest
from rest_framework import status
from .factories import ProductFactory, UserFactory


@pytest.fixture
def product(db):
    return ProductFactory(stock=10, price=Decimal("10.00"))


@pytest.mark.django_db
class TestOrderCreate:
    url = "/api/orders/"

    def test_create_valid_order(self, authenticated_client, product):
        payload = {
            "items": [
                {"product": product.id, "quantity": 2},
            ],
        }
        response = authenticated_client.post(self.url, payload, format="json")
        assert response.status_code == status.HTTP_201_CREATED

    def test_create_without_items(self, authenticated_client):
        response = authenticated_client.post(self.url, {"items": []}, format="json")
        assert response.status_code == status.HTTP_400_BAD_REQUEST

    def test_insufficient_stock(self, authenticated_client, product):
        payload = {
            "items": [
                {"product": product.id, "quantity": 100},
            ],
        }
        response = authenticated_client.post(self.url, payload, format="json")
        assert response.status_code == status.HTTP_409_CONFLICT
